export const RESOURCE_ARTICLES = RESOURCE_ARTICLE_DATA.map(article => ({ ...article, audience: article.audience || (article.slug.startsWith('reader-') ? 'readers' : AUTHOR_ONLY_RESOURCE_SLUGS.has(article.slug) ? 'authors' : 'all') }));
